def set_path(data, path, value):
    key, *rest = path.split('.')
    if not rest:
        return {**data, key: value}
    child = data.get(key)
    if not isinstance(child, dict):
        child = {}
    return {**data, key: set_path(child, '.'.join(rest), value)}

