from collections import Counter, defaultdict

def parse_line(line):
    parts = line.split()
    if len(parts) != 4:
        return None
    ts, level, endpoint, ms = parts
    if level not in ('INFO', 'WARN', 'ERROR'):
        return None
    try:
        return {'ts': ts, 'level': level, 'endpoint': endpoint, 'ms': float(ms)}
    except ValueError:
        return None


def analyze(lines):
    levels = Counter()
    latency = defaultdict(list)
    errors = Counter()
    bad = []
    for i, line in enumerate(lines, 1):
        record = parse_line(line)
        if record is None:
            bad.append(i)
            continue
        levels[record['level']] += 1
        latency[record['endpoint']].append(record['ms'])
        if record['level'] == 'ERROR':
            errors[record['endpoint']] += 1
    stats = {
        endpoint: {
            'n': len(values),
            'avg_ms': round(sum(values) / len(values), 1),
            'max_ms': max(values),
        } for endpoint, values in latency.items()
    }
    return {'levels': dict(levels), 'endpoints': stats, 'error_codes': errors.most_common(2), 'bad_lines': bad}


