import json, os, tempfile
from collections import defaultdict

def deep_merge(base, override):
    merged = dict(base)
    for key, value in override.items():
        if isinstance(value, dict) and isinstance(merged.get(key), dict):
            merged[key] = deep_merge(merged[key], value)
        else:
            merged[key] = value
    return merged


def flatten(data, prefix=''):
    out = {}
    for key, value in data.items():
        path = f'{prefix}{key}'
        if isinstance(value, dict):
            out.update(flatten(value, path + '.'))
        else:
            out[path] = value
    return out


def diff(a, b):
    fa, fb = flatten(a), flatten(b)
    return {
        'added': {k: fb[k] for k in fb.keys() - fa.keys()},
        'removed': {k: fa[k] for k in fa.keys() - fb.keys()},
        'changed': {k: (fa[k], fb[k]) for k in fa.keys() & fb.keys() if fa[k] != fb[k]},
    }


def validate(config, required):
    problems = []
    for path, type_name in required.items():
        node = config
        for part in path.split('.'):
            if not isinstance(node, dict) or part not in node:
                problems.append(f'missing: {path}')
                node = None
                break
            node = node[part]
        if node is not None and type(node).__name__ != type_name:
            problems.append(f'{path} should be {type_name}, got {type(node).__name__}')
    return problems


def mask(config, secret_keys=('password', 'token', 'secret')):
    def walk(node):
        if isinstance(node, dict):
            return {k: ('***' if any(s in k.lower() for s in secret_keys) else walk(v)) for k, v in node.items()}
        return node
    return walk(config)


def save(config, path):
    directory = os.path.dirname(path) or '.'
    fd, tmp = tempfile.mkstemp(dir=directory, suffix='.tmp')
    try:
        with os.fdopen(fd, 'w') as f:
            json.dump(config, f, indent=2, sort_keys=True)
        os.replace(tmp, path)
    finally:
        if os.path.exists(tmp):
            os.remove(tmp)
    return path


def load(path):
    if not os.path.exists(path):
        return {}
    try:
        with open(path) as f:
            return json.load(f)
    except json.JSONDecodeError:
        os.replace(path, path + '.corrupt')
        return {}


